function backoffDelay(attempt, { baseMs, maxMs, random }) {
  const ceiling = Math.min(maxMs, baseMs * 2 ** attempt);
  return random() * ceiling; // full jitter: anywhere in [0, ceiling)
}

async function retryWithBackoff(fn, { retries, baseMs, maxMs, random, sleep }) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      const outOfRetries = attempt >= retries;
      const permanent = err && err.retryable === false;
      if (outOfRetries || permanent) throw err;
      await sleep(backoffDelay(attempt, { baseMs, maxMs, random }));
    }
  }
}

tests.code:
const o = { baseMs: 100, maxMs: 1000, random: () => 0.5 };
assertEqual(backoffDelay(0, o), 50);
assertEqual(backoffDelay(3, o), 400);
assertEqual(backoffDelay(0, { ...o, random: () => 0 }), 0);

const waits = [];
const r = await retryWithBackoff(async () => 'ok', { retries: 3, baseMs: 100, maxMs: 1000, random: () => 1, sleep: async ms => { waits.push(ms); } });
assertEqual(r, 'ok');
assertEqual(waits, []);

const waits = []; const seen = [];
const fn = async (attempt) => { seen.push(attempt); if (attempt < 2) throw new Error('503'); return 'audio.mp3'; };
const r = await retryWithBackoff(fn, { retries: 5, baseMs: 100, maxMs: 1000, random: () => 1, sleep: async ms => { waits.push(ms); } });
assertEqual(r, 'audio.mp3');
assertEqual(seen, [0, 1, 2]);
assertEqual(waits, [100, 200]);

let calls = 0; const waits = [];
const fn = async () => { calls++; throw new Error('fail #' + calls); };
let caught = null;
try { await retryWithBackoff(fn, { retries: 3, baseMs: 10, maxMs: 1000, random: () => 1, sleep: async ms => { waits.push(ms); } }); }
catch (e) { caught = e; }
assert(caught, 'should throw');
assertEqual(caught.message, 'fail #4');
assertEqual(calls, 4, 'retries: 3 means 4 calls total');
assertEqual(waits, [10, 20, 40]);

let calls = 0; const waits = [];
const fn = async () => { calls++; const e = new Error('400 bad voice id'); e.retryable = false; throw e; };
let caught = null;
try { await retryWithBackoff(fn, { retries: 5, baseMs: 100, maxMs: 1000, random: () => 1, sleep: async ms => { waits.push(ms); } }); }
catch (e) { caught = e; }
assertEqual(caught && caught.message, '400 bad voice id');
assertEqual(calls, 1);
assertEqual(waits, []);

let calls = 0;
let threw = false;
try { await retryWithBackoff(async () => { calls++; throw new Error('x'); }, { retries: 0, baseMs: 100, maxMs: 1000, random: () => 1, sleep: async () => {} }); }
catch (e) { threw = true; }
assert(threw, 'should throw');
assertEqual(calls, 1);
